// 1. Validate Canonical HMAC-SHA256 Signature and Check Replay Window
const crypto = require('crypto');
const secret = $env.DIAVN_WEBHOOK_SECRET || 'diavn-default-shared-secret-for-n8n-auth';

const headers = $node["DIAVN Webhook Receiver"].json.headers || {};
const body = $node["DIAVN Webhook Receiver"].json.body || {};

const rawSignature = headers['x-diavn-signature'] || headers['X-DIAVN-Signature'] || '';
const timestamp = headers['x-diavn-timestamp'] || headers['X-DIAVN-Timestamp'] || body.timestamp || '';
const eventId = headers['x-diavn-event-id'] || headers['X-DIAVN-Event-ID'] || body.event_id;

if (!rawSignature || !timestamp) {
  throw new Error('Missing signature (X-DIAVN-Signature) or timestamp (X-DIAVN-Timestamp) header');
}

// 5-minute replay window check (300 seconds)
const now = Date.now();
const eventTime = new Date(timestamp).getTime();
if (isNaN(eventTime) || Math.abs(now - eventTime) > 300000) {
  throw new Error('Webhook timestamp outside acceptable 300s replay window');
}

// Canonical HMAC check: HMAC-SHA256(timestamp + '.' + JSON.stringify(body), secret)
const cleanSig = rawSignature.replace(/^sha256=/, '');
const expectedSig = crypto.createHmac('sha256', secret).update(timestamp + '.' + JSON.stringify(body)).digest('hex');

if (cleanSig !== expectedSig) {
  throw new Error('Canonical HMAC signature verification mismatch');
}

return [{
  json: {
    ...body,
    event_id: eventId,
    signature_valid: true,
    authenticated_at: new Date().toISOString()
  }
}];

// 2. Durable Idempotency & Deduplication Check
// Guarantees an event_id is only processed once for physical field dispatch
const staticData = getWorkflowStaticData('global');
staticData.processedEvents = staticData.processedEvents || {};

const eventId = $json.event_id;
if (staticData.processedEvents[eventId]) {
  return [{
    json: {
      ...$json,
      is_duplicate: true,
      status: 'duplicate_suppressed',
      first_seen_at: staticData.processedEvents[eventId]
    }
  }];
}

// Mark event as processed
staticData.processedEvents[eventId] = new Date().toISOString();
return [{
  json: {
    ...$json,
    is_duplicate: false
  }
}];

// 3. Create Operational Field Verification Dispatch Package (Defensive Routing of Backend Task)
const data = $json;

const caseIdentifier = data.case_number || data.case_id;
const taskId = data.verification_task_id || `TSK-${caseIdentifier}-01`;
const baseOrigin = data.case_url ? data.case_url.split('/cases/')[0] : 'http://localhost:3000';
const fieldCaptureUrl = `${baseOrigin}/field/capture?caseId=${caseIdentifier}`;

const fieldDispatchNotice = {
  dispatch_id: `DISPATCH-${caseIdentifier}-${Date.now().toString(36).toUpperCase()}`,
  case_number: data.case_number || data.case_id,
  case_id: data.case_id,
  risk_score: data.risk_score,
  risk_band: data.risk_band,
  task_id: taskId,
  task_type: 'physical_site_verification',
  priority: 'CRITICAL_HIGH',
  operational_instructions: data.recommended_action || 'Execute on-site physical serial plate and photo verification',
  active_anomalies: data.top_anomalies || [],
  case_dossier_url: data.case_url,
  field_capture_url: fieldCaptureUrl,
  dispatched_at: new Date().toISOString(),
  event_reference: data.event_id
};

console.log(`[DIAVN Operational Dispatch] Case ${caseIdentifier} -> Field Verification Queue. Task ID: ${taskId}`);
console.log(`Field Capture Link: ${fieldDispatchNotice.field_capture_url}`);

return [{
  json: {
    ...fieldDispatchNotice,
    status: 'field_verification_enqueued',
    workflow_stage: 'PHYSICAL_INSPECTION_PENDING'
  }
}];

// 4. Audit Log for Low/Medium or Duplicate Lifecycle Events
const data = $json;
const isDup = data.is_duplicate === true;

const logEntry = {
  event_id: data.event_id,
  case_number: data.case_number || data.case_id,
  event_type: data.event_type,
  risk_score: data.risk_score,
  risk_band: data.risk_band,
  disposition: isDup ? 'DUPLICATE_SUPPRESSED' : 'STANDARD_AUDIT_LOGGED',
  logged_at: new Date().toISOString()
};

console.log(`[DIAVN Outbox Audit] ${logEntry.disposition}: Event ${data.event_id} (Score: ${data.risk_score})`);
return [{ json: logEntry }];
